        for (int i = 0; i <= n; i++) {
            fast = fast.next; // 先拉开n+1条边
        }
        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }
        slow.next = slow.next.next;
        return dummy.next;
    }
}

